1	'use strict';
2	
3	const fs = require('node:fs/promises');
4	const path = require('node:path');
5	const { round6 } = require('./stats');
6	const { parseArgs, EXIT_OK, EXIT_USAGE, EXIT_OUTPUT_ERROR } = require('./collect');
7	const {
8	  loadInput,
9	  buildCompareResult,
10	  decide,
11	  parseNumberOption,
12	  DEFAULT_ALPHA,
13	  DEFAULT_MIN_CHANGE_PERCENT,
14	} = require('./compare');
15	
16	const KNOWN_KEYS = new Set(['manifest', 'output', 'alpha', 'min-change-percent']);
17	
18	function fail(message) {
19	  process.stderr.write(`perf-regress: ${message}\n`);
20	  return EXIT_USAGE;
21	}
22	
23	// Benjamini–Hochberg 校正：m 个 p 值升序后记 p_(1)<=...<=p_(m)，
24	// q_(i) = min(1, min over j>=i (m*p_(j)/j))，再映回原序，保留六位小数。
25	function benjaminiHochberg(pValues) {
26	  const m = pValues.length;
27	  const order = Array.from({ length: m }, (_, i) => i)
28	    .sort((a, b) => pValues[a] - pValues[b]);
29	  const adjusted = new Array(m);
30	  let running = 1;
31	  // 从最大秩向最小秩扫描，累积 min
32	  for (let rank = m; rank >= 1; rank--) {
33	    const index = order[rank - 1];
34	    running = Math.min(running, (m * pValues[index]) / rank);
35	    adjusted[index] = round6(Math.min(1, running));
36	  }
37	  return adjusted;
38	}
39	
40	// 多项归因百分比的中位数：null 按正无穷参与比较；结果为正无穷时写回 null。
41	// 空序列（无具可比性 case 的 ab-suite）同样写 null。
42	function medianPercent(values) {
43	  if (values.length === 0) {
44	    return null;
45	  }
46	  const sorted = values
47	    .map((v) => (v === null ? Infinity : v))
48	    .sort((a, b) => a - b);
49	  const n = sorted.length;
50	  const mid = n >> 1;
