  for (const factor of ['central_tendency', 'tail_latency', 'variability', 'none']) {
    const count = factorCounts.get(factor) || 0;
    if (count > bestCount) {
      bestCount = count;
      suiteDominantFactor = factor;
    }
  }
  return {
    total_cases: caseReports.length,
